<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Nexora Return</title>
<style>
  :root {
    --bg-header: #0B1E3D;
    --bg-dark: #1B3A6B;
    --bg-card: #0B1E3D;
    --text-light: #FFFFFF;
    --text-muted: #9FB3D1;
    --border-soft: rgba(255,255,255,0.08);
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    font-family: 'Segoe UI', Arial, sans-serif;
    background: var(--bg-dark);
    color: var(--text-light);
  }

  /* ===== Navbar ===== */
  .navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 40px;
    background: var(--bg-header);
    border-bottom: 1px solid var(--border-soft);
  }

  .brand {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .logo {
    width: 46px;
    height: 50px;
    object-fit: contain;
  }

  .brand-text .title {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 1px;
  }

  .brand-text .subtitle {
    font-size: 11px;
    color: #3B82F6;
    letter-spacing: 1px;
  }

  .nav-links {
    display: flex;
    gap: 36px;
  }

  .nav-links a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 15px;
    font-weight: 500;
  }

  .nav-links a.active {
    color: var(--text-light);
    font-weight: 700;
  }

  /* ===== Main layout ===== */
  .main-layout {
    display: flex;
    gap: 24px;
    padding: 24px 40px 60px;
    align-items: flex-start;
  }

  /* ===== Order queue panel ===== */
  .queue-panel {
    background: var(--bg-card);
    border: 1px solid var(--border-soft);
    border-radius: 12px;
    flex: 1;
    min-width: 0;
    overflow: hidden;
  }

  .queue-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 24px;
    border-bottom: 1px solid var(--border-soft);
  }

  .queue-title {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 18px;
    font-weight: 700;
  }

  .queue-icon {
    width: 18px;
    height: 18px;
    display: inline-block;
    border: 2px solid var(--text-light);
    border-radius: 3px;
    position: relative;
  }
  .queue-icon::before, .queue-icon::after {
    content: "";
    position: absolute;
    background: var(--text-light);
    left: 3px;
    right: 3px;
    height: 2px;
  }
  .queue-icon::before { top: 5px; }
  .queue-icon::after { top: 9px; }

  .queue-tabs {
    display: flex;
    gap: 24px;
    font-size: 14px;
    color: var(--text-muted);
  }

  .queue-tabs .active-tab {
    color: var(--text-light);
    font-weight: 700;
  }

  table {
    width: 100%;
    border-collapse: collapse;
  }

  thead th {
    text-align: left;
    font-size: 14px;
    font-weight: 700;
    padding: 16px 24px;
    border-bottom: 1px solid var(--border-soft);
  }

  tbody td {
    padding: 14px 24px;
    font-size: 14px;
    border-bottom: 1px solid var(--border-soft);
  }

  tbody tr:hover {
    background: rgba(255,255,255,0.03);
  }

  .order-id { color: var(--text-muted); }
  .customer { font-weight: 700; }
  .product { color: var(--text-muted); }

  .status-badge {
    background: rgba(255,255,255,0.1);
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 700;
    padding: 5px 12px;
    border-radius: 6px;
    letter-spacing: 0.5px;
  }

  .priority-badge {
    background: #7F1D2E;
    color: #FCA5B1;
    font-size: 11px;
    font-weight: 700;
    padding: 4px 10px;
    border-radius: 10px;
  }

  .due-date {
    color: #F87171;
    font-weight: 600;
  }

  .pick-btn {
    background: rgba(255,255,255,0.12);
    color: var(--text-light);
    border: 1px solid var(--border-soft);
    border-radius: 18px;
    padding: 7px 16px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
  }

  .pick-btn:hover {
    background: rgba(255,255,255,0.2);
  }

  /* ===== Sidebar ===== */
  .sidebar {
    display: flex;
    flex-direction: column;
    gap: 24px;
    width: 320px;
    flex-shrink: 0;
  }

  .side-panel {
    background: var(--bg-card);
    border: 1px solid var(--border-soft);
    border-radius: 12px;
    overflow: hidden;
  }

  .side-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 18px 24px;
    border-bottom: 1px solid var(--border-soft);
    font-size: 18px;
    font-weight: 700;
  }

  .side-icon {
    width: 18px;
    height: 18px;
    color: var(--text-light);
  }

  .side-body {
    min-height: 360px;
  }

  .side-body .row {
    height: 46px;
    border-bottom: 1px solid var(--border-soft);
  }

  .side-body.short .row {
    height: 46px;
  }
</style>
</head>
